        submit_ok(&mut g, p, Action::Pass);
    }
    assert!(!g.state.creature_died_this_turn);
    assert!(g.state.nontoken_creature_deaths_this_turn.is_empty());
    let second = hand_card(&g, P0, card("Caller of the Claw"));
